struct self_test_hash_vector {
        IMB_HASH_ALG hash_mode;
        const uint8_t *hash_key; /* cmac, hmac, gmac */
        size_t hash_key_size;    /* key size in bytes */
        const uint8_t *message;
        size_t message_size;
        const uint8_t *tag;
        size_t tag_size;
        const uint8_t *hash_iv; /* gmac */
        size_t hash_iv_size;
        const char *description;
};

