#define ADD_GCM_VECTOR(_key, _iv, _aad, _plain, _cipher, _tag, _descr)                             \
        { IMB_AUTH_AES_GMAC, IMB_CIPHER_GCM, _key,         sizeof(_key), _iv,                      \
          sizeof(_iv),       _aad,           sizeof(_aad), _plain,       sizeof(_plain),           \
          _cipher,           _tag,           sizeof(_tag), _descr }

