struct self_test_ml_dsa_vector {
        IMB_ML_DSA_ALG alg;
        const uint8_t *sk;
        size_t sk_len;
        size_t pk_len;
        size_t sig_len;
        const uint8_t *msg;
        size_t msg_len;
        const uint8_t *ctx;
        size_t ctx_len;
        const uint8_t *sig;
        const char *description;
};

#define ADD_ML_DSA_VECTOR(_alg, _sk, _pk_len, _sig_len, _msg, _ctx, _sig, _descr)                  \
        { _alg,         _sk,  sizeof(_sk),  _pk_len, _sig_len, _msg,                               \
          sizeof(_msg), _ctx, sizeof(_ctx), _sig,    _descr }

static const struct self_test_ml_dsa_vector ml_dsa_vectors[] = {
        ADD_ML_DSA_VECTOR(IMB_ML_DSA_44, ml_dsa_44_sk, IMB_ML_DSA_44_PUBKEY_BYTES,
                          IMB_ML_DSA_44_SIG_BYTES, ml_dsa_44_msg, ml_dsa_44_context, ml_dsa_44_sig,
                          "ML-DSA-44"),
        ADD_ML_DSA_VECTOR(IMB_ML_DSA_65, ml_dsa_65_sk, IMB_ML_DSA_65_PUBKEY_BYTES,
                          IMB_ML_DSA_65_SIG_BYTES, ml_dsa_65_msg, ml_dsa_65_context, ml_dsa_65_sig,
                          "ML-DSA-65"),
        ADD_ML_DSA_VECTOR(IMB_ML_DSA_87, ml_dsa_87_sk, IMB_ML_DSA_87_PUBKEY_BYTES,
                          IMB_ML_DSA_87_SIG_BYTES, ml_dsa_87_msg, ml_dsa_87_context, ml_dsa_87_sig,
                          "ML-DSA-87"),
};

/*
 * KAT covers the public FIPS 204 external interface (ML-DSA.Sign/Verify,
 * encode = 1) with deterministic signing (rnd = 0), matching the ACVP
 * capability scope implemented by imb-acvp. imb_ml_dsa_pubkey_from_privkey()
 * is exercised here as a standalone key-derivation self-check; the actual
 * sign/verify round-trip below runs against the private key bound via
 * imb_ml_dsa_set_privkey(), which also carries the derived public
 * component, so only the private key needs to be embedded as test data.
 */
static int
self_test_ml_dsa(IMB_MGR *p_mgr, const struct self_test_ml_dsa_vector *v)
{
        IMB_ML_DSA *handle = NULL;
        uint8_t pk[IMB_ML_DSA_87_PUBKEY_BYTES];
        uint8_t sig[IMB_ML_DSA_87_SIG_BYTES];
        uint8_t msg[256];
        const uint8_t zero_rnd[32] = { 0 };
        size_t sig_len = 0;
        int ret = 0;

        IMB_ASSERT(v->msg_len <= sizeof(msg));
        if (v->msg_len > sizeof(msg))
                return 0;

        memcpy(msg, v->msg, v->msg_len);

        if (make_callback(p_mgr, IMB_SELF_TEST_PHASE_CORRUPT, NULL, NULL) == 0)
                msg[0] ^= 1;

        if (imb_ml_dsa_new(p_mgr, v->alg, &handle) != 0)
                return 0;

        /* Standalone key-derivation self-check (does not bind a key). */
        if (imb_ml_dsa_pubkey_from_privkey(handle, v->sk, pk) != 0)
                goto end;

        if (imb_ml_dsa_set_privkey(handle, v->sk) != 0)
                goto end;

        {
                IMB_ML_DSA_SIGN_PARAMS sign_params;

                sign_params.ctx = v->ctx;
                sign_params.ctx_len = v->ctx_len;
                sign_params.rnd_32 = zero_rnd;

                if (imb_ml_dsa_sign(handle, sig, &sig_len, msg, v->msg_len, &sign_params) != 0)
                        goto end;
        }

        if (sig_len != v->sig_len || memcmp(sig, v->sig, v->sig_len) != 0)
                goto end;

        {
                IMB_ML_DSA_VERIFY_PARAMS verify_params;

                verify_params.ctx = v->ctx;
                verify_params.ctx_len = v->ctx_len;

                if (imb_ml_dsa_verify(handle, msg, v->msg_len, sig, sig_len, &verify_params) != 0)
                        goto end;
        }

        ret = 1;
end:
        imb_ml_dsa_free(handle);
        return ret;
}

static int
self_test_ml_dsas(IMB_MGR *p_mgr)
{
        int ret = 1;

        for (unsigned i = 0; i < IMB_DIM(ml_dsa_vectors); i++) {
                const struct self_test_ml_dsa_vector *v = &ml_dsa_vectors[i];

                (void) make_callback(p_mgr, IMB_SELF_TEST_PHASE_START,
                                     IMB_SELF_TEST_TYPE_KAT_SIGNATURE, v->description);

                const int r = self_test_ml_dsa(p_mgr, v);

                if (r == 0) {
                        ret = 0;
                        (void) make_callback(p_mgr, IMB_SELF_TEST_PHASE_FAIL, NULL, NULL);
                } else {
                        (void) make_callback(p_mgr, IMB_SELF_TEST_PHASE_PASS, NULL, NULL);
                }
        }

        return ret;
}

